contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);
        require(amount > 0);

        c.Command{value: amount}(address(this), bytes("")); if (__ESBMC_reverted()) return;

        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        c.withdraw(); if (__ESBMC_reverted()) return;

        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;

        assert(afterCBalance == 0 && afterThisBalance == beforeThisBalance + beforeCBalance);
    }
}

