// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    MultiplicatorX3 c;

    function setUp() public {
        c = new MultiplicatorX3();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount > 0);
        try c.Command{value: amount}(address(this), bytes("")) {} catch { return; }
        uint beforeCBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        try c.withdraw() {} catch { return; }
        uint afterCBalance = address(c).balance;
        uint afterThisBalance = address(this).balance;
        assertTrue(afterCBalance == 0 && afterThisBalance == beforeThisBalance + beforeCBalance);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
